package uk.co.traynor.novaos.preview
import android.webkit.*
import android.view.View
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

@RunWith(AndroidJUnit4::class)
class FavouritesAcceptanceTest{
 @get:Rule val rule=createAndroidComposeRule<MainActivity>()
 private val p get()=rule.activity.browserPool
 private fun js(v:WebView,s:String):String{var value="";val done=CountDownLatch(1);rule.runOnUiThread{v.evaluateJavascript(s){value=it;done.countDown()}};assertTrue(done.await(10,TimeUnit.SECONDS));return value}
 private fun html(mode:String="normal")="""<script>window.filterClicks=0;window.sent=0;window.deleted=0;window.secretReads=0;window.allowFilter=${mode!="stuck"};Object.defineProperty(document,'cookie',{get(){secretReads++;return 'SYNTHETIC_TOKEN'}});function favour(){filterClicks++;if(allowFilter){document.getElementById('all').setAttribute('aria-pressed','false');document.getElementById('fav').setAttribute('aria-pressed','true')}};</script>${if(mode=="login")"<div data-testid='qr-code'></div>"else ""}<div id='side'>${if(mode in listOf("normal","stuck","contradiction"))"<div id='filters' role='tablist'><button id='all' aria-pressed='true'>All</button><button id='fav' aria-pressed='false' ${if(mode=="contradiction")"aria-selected='true'"else ""} onclick='favour()'><span>Favourites</span><span aria-hidden='true'>42</span></button><button aria-pressed='false'>Unread</button><button aria-pressed='false'>Groups</button></div>"else ""}${if(mode!="login")"<div id='pane-side'><div role='grid'><div role='row'>SYNTHETIC PRIVATE CONTACT AND MESSAGE</div></div></div>"else ""}</div><button onclick='sent++'>Send</button><button onclick='deleted++'>Delete</button>"""
 private fun fixture(mode:String="normal",profile:String="primary"):PreviewTab{lateinit var tab:PreviewTab;rule.runOnUiThread{tab=p.create(standaloneBrowser.copy(id="wa-favourites",url="https://web.whatsapp.com/"),profile,false);p.select(tab);val delegate=tab.view.webViewClient;tab.view.webViewClient=object:WebViewClient(){override fun shouldInterceptRequest(v:WebView,r:WebResourceRequest):WebResourceResponse?=if(r.isForMainFrame&&r.url.host=="web.whatsapp.com")WebResourceResponse("text/html","UTF-8",java.io.ByteArrayInputStream(html(mode).toByteArray()))else null;override fun onPageStarted(v:WebView,url:String,b:android.graphics.Bitmap?){delegate.onPageStarted(v,url,b)};override fun onPageFinished(v:WebView,url:String){delegate.onPageFinished(v,url)};override fun shouldOverrideUrlLoading(v:WebView,r:WebResourceRequest)=delegate.shouldOverrideUrlLoading(v,r)};p.navigate(tab,"https://web.whatsapp.com/")};rule.waitUntil(10000){tab.progress==100&&js(tab.view,"typeof window.filterClicks")=="\"number\""};return tab}
 private fun enable(t:PreviewTab){rule.runOnUiThread{p.requireFriends(t,true);assertEquals(View.INVISIBLE,t.view.visibility)}}
 private fun active(t:PreviewTab){rule.waitUntil(15000){t.favouritesState=="FAVOURITES_ACTIVE"&&t.favouritesVerified};assertEquals("true",js(t.view,"document.getElementById('fav').getAttribute('aria-pressed')==='true'&&document.getElementById('all').getAttribute('aria-pressed')==='false'"));rule.runOnUiThread{assertEquals(View.VISIBLE,t.view.visibility)}}
 private fun launchChat(){rule.onNodeWithTag("open-apps").performClick();rule.onNodeWithTag("drawer-search").performTextInput("Nova Chat");rule.onNodeWithTag("app-chat").performClick()}
 @Before fun reset(){rule.runOnUiThread{val d=rule.activity.previewData;if(d.state.current!="primary")d.switchProfile();d.change{Profile()};p.closeAll();p.library.setFlag("friends-required:primary:wa-favourites",false);p.library.setFlag("friends-required:hidden:wa-favourites",false);p.library.setFlag("friends-site:primary:web.whatsapp.com",false)}}
 @Test fun nativeActivationIsVerifiedBadgeIsIgnoredAndActiveFilterIsNotClickedAgain(){val t=fixture();enable(t);active(t);assertEquals("1",js(t.view,"filterClicks"));assertEquals("0",js(t.view,"secretReads+sent+deleted"));rule.runOnUiThread{p.favourites.ensure(t,true)};active(t);assertEquals("1",js(t.view,"filterClicks"));assertEquals("1",js(t.view,"document.querySelectorAll('[role=row]').length"))}
 @Test fun loadingRemainsConcealedUntilActualFilterControlsExist(){val t=fixture("missing");enable(t);rule.waitUntil(8000){t.favouritesState=="FILTER_UNAVAILABLE"};rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)};js(t.view,"document.getElementById('side').insertAdjacentHTML('afterbegin',`<div role='tablist'><button id='all' aria-pressed='true'>All</button><button id='fav' aria-pressed='false' onclick='favour()'>Favorites</button><button aria-pressed='false'>Unread</button></div>`)");active(t)}
 @Test fun reloadRestoresFavouritesWithoutReplacingViewOrLosingSessionStorage(){val t=fixture();enable(t);active(t);val view=t.view;js(view,"sessionStorage.setItem('nova-retained','kept')");val revision=t.navigationRevision;rule.runOnUiThread{p.reload(t);assertEquals(View.INVISIBLE,view.visibility);assertFalse(t.favouritesVerified)};rule.waitUntil(10000){t.navigationRevision>revision};active(t);rule.runOnUiThread{assertSame(view,t.view)};assertEquals("\"kept\"",js(view,"sessionStorage.getItem('nova-retained')"));assertEquals("1",js(view,"filterClicks"))}
 @Test fun changedSelectionIsCoveredBeforeRestorationAndAmbiguousDomFailsClosed(){val t=fixture();enable(t);active(t);js(t.view,"window.coveredBeforeRestore=null;const spy=new MutationObserver(()=>{window.coveredBeforeRestore=document.documentElement.hasAttribute('data-nova-favourites-checking');spy.disconnect()});spy.observe(document.getElementById('filters'),{subtree:true,attributes:true,attributeFilter:['aria-pressed']});document.getElementById('fav').setAttribute('aria-pressed','false');document.getElementById('all').setAttribute('aria-pressed','true')");rule.waitUntil(10000){js(t.view,"filterClicks")=="2"};active(t);assertEquals("true",js(t.view,"window.coveredBeforeRestore"));js(t.view,"document.getElementById('side').insertAdjacentHTML('afterbegin',document.getElementById('filters').outerHTML)");rule.waitUntil(8000){t.favouritesState=="FILTER_UNAVAILABLE"};rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)}}
 @Test fun missingAndConflictingStatesCannotAuthoriseReveal(){val t=fixture("contradiction");enable(t);rule.waitUntil(8000){t.favouritesState=="FILTER_UNAVAILABLE"};assertEquals("0",js(t.view,"filterClicks"));rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)}}
 @Test fun failedSelectionTimesOutAndExplicitRetryCanRecover(){val t=fixture("stuck");enable(t);rule.waitUntil(15000){t.favouritesState=="COMPATIBILITY_ERROR"};assertEquals("1",js(t.view,"filterClicks"));rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)};js(t.view,"allowFilter=true");rule.runOnUiThread{p.favourites.ensure(t,true)};active(t);assertEquals("2",js(t.view,"filterClicks"))}
 @Test fun loginIsReportedWithoutChangingLinkedDeviceOrAccount(){val t=fixture("login");enable(t);rule.waitUntil(8000){t.favouritesState=="LOGIN_REQUIRED"};assertEquals("0",js(t.view,"sent+deleted+secretReads+filterClicks"));rule.runOnUiThread{assertEquals(View.INVISIBLE,t.view.visibility)}}
 @Test fun explicitNormalExitDisconnectsAdapterAndUsesSamePage(){val t=fixture();launchChat();active(t);rule.onNodeWithContentDescription("Open normal WhatsApp").performClick();rule.onNodeWithText("Stay in Friends Mode").performClick();rule.runOnUiThread{assertTrue(p.friendsRequested(t))};rule.onNodeWithContentDescription("Open normal WhatsApp").performClick();rule.onNodeWithText("Open unfiltered WhatsApp").performClick();rule.waitUntil(5000){!p.friendsRequested(t)};js(t.view,"document.getElementById('fav').setAttribute('aria-pressed','false');document.getElementById('all').setAttribute('aria-pressed','true')");android.os.SystemClock.sleep(1200);assertEquals("true",js(t.view,"document.getElementById('all').getAttribute('aria-pressed')==='true'&&typeof window.__novaFav10==='undefined'"));rule.runOnUiThread{assertSame(t.view,p.active!!.view);assertEquals(View.VISIBLE,t.view.visibility)}}
 @Test fun homeAppSwitchRecreationAndFoldKeepOriginalWebViewAndFavourites(){val t=fixture();launchChat();active(t);val view=t.view;rule.onNodeWithTag("nova-home").performClick();rule.runOnUiThread{val other=p.create(standaloneBrowser.copy(id="other",url="https://example.com/"),"primary",false);p.select(other)};launchChat();active(t);rule.runOnUiThread{assertSame(view,p.active!!.view)};rule.activityRule.scenario.recreate();rule.waitForIdle();active(t)
  fun shell(s:String){val fd=InstrumentationRegistry.getInstrumentation().uiAutomation.executeShellCommand(s);android.os.ParcelFileDescriptor.AutoCloseInputStream(fd).use{it.readBytes()}}
  try{shell("wm density 420");for(size in listOf("904x2316","1840x2208","2316x904")){shell("wm size $size");android.os.SystemClock.sleep(1000);rule.waitForIdle();active(t);rule.onNodeWithTag("nova-chat-lite").assertIsDisplayed();rule.onNodeWithTag("nova-navigation").assertIsDisplayed();rule.runOnUiThread{assertSame(view,p.active!!.view)}}}finally{shell("wm size reset");shell("wm density reset")}
  assertEquals("1",js(view,"filterClicks"))
 }
 @Test fun concurrentNativeSelectionsCannotAuthoriseReveal(){val t=fixture();enable(t);active(t);js(t.view,"document.querySelectorAll('#filters button')[3].setAttribute('aria-pressed','true')");rule.waitUntil(8000){t.favouritesState=="COMPATIBILITY_ERROR"};rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)}}
 @Test fun inactivePreviewProfileDoesNotRunFilterInteractions(){val t=fixture(profile="hidden");rule.runOnUiThread{p.requireFriends(t,true);p.favourites.ensure(t,true)};android.os.SystemClock.sleep(1200);assertEquals("0",js(t.view,"filterClicks"));rule.runOnUiThread{assertFalse(t.favouritesVerified);assertEquals(View.INVISIBLE,t.view.visibility)}}
}
